const test=require('node:test'),assert=require('node:assert/strict'),path=require('node:path'),fs=require('node:fs'),R=require('./delivery-workbench-runtime.cjs');
const query={scope_kind:'store',store_id:'3',delivery_id:'7'},start=async(options={},params=query)=>{const r=R.runtime(options);await r.start(params);return r;},writes=r=>r.calls.filter(call=>call.method==='POST'&&call.url.endsWith('/writeoff'));
test('delivery registration preserves all original 104 pages and startup page',()=>{const current=JSON.parse(fs.readFileSync(path.join(R.root,'src/pages.json'))),before=JSON.parse(fs.readFileSync(path.resolve(R.root,'../../.cache/delivery-workbench-uniapp-20261003/before/view/uniapp-ts/src/pages.json')));assert.equal(before.pages.length,104);assert.equal(current.pages.length,108);assert.equal(current.pages[0].path,'pages/index/index');assert.equal(new Set(current.pages.map(row=>row.path)).size,108);for(const row of before.pages)assert.ok(current.pages.some(page=>page.path===row.path));});
test('anonymous sends no authenticated delivery request',async()=>{const r=await start({anonymous:true});try{assert.equal(r.calls.length,0);assert.match(r.page.controller.error.value,/登录/);}finally{r.stop();}});
test('single or multiple identities require an explicit selection',async()=>{for(const contexts of [[R.scope()],[R.scope(),R.scope('platform',0,8)]]){const r=await start({contexts},{});try{assert.equal(r.calls.length,1);assert.equal(r.page.controller.selected.value,null);assert.equal(r.page.orders.value.length,0);r.page.controller.chooseScope({detail:{value:0}});await R.tick();assert.equal(r.page.orders.value.length,1);assert.ok(r.calls.slice(1).filter(call=>!call.url.endsWith('/context')).every(call=>call.data.store_id===3&&call.data.delivery_id===7&&call.data.scope_kind==='store'&&call.data.scope_key===R.hash));}finally{r.stop();}}});
test('selected platform remains platform and never inherits store scope',async()=>{const r=await start({contexts:[R.scope('platform',0,8)]},{scope_kind:'platform',store_id:'0',delivery_id:'8'});try{assert.equal(r.page.controller.selected.value.store_id,0);assert.ok(r.calls.every(call=>call.data.store_id===0));assert.equal(r.page.statistics.value.send_price,'50.25');}finally{r.stop();}});
test('wrong current actor is rejected before PII reads and explicit refresh recovers',async()=>{let bad=true;const r=await start({send(call,p){if(p.endsWith('/context')&&bad)return{data:R.envelope({contexts:[R.identity()],conflicts:[],selected:R.scope()},99)};}});try{assert.equal(r.calls.length,1);assert.equal(r.page.orders.value.length,0);bad=false;await r.page.controller.load();assert.equal(r.page.orders.value.length,1);}finally{r.stop();}});
test('scope tuple and consistency changes reject mixed statistics',async()=>{for(const foreign of ['scope','consistency']){const r=await start({send(call,p){if(p.endsWith('/statistics'))return{data:R.envelope({unsend:2,send:3,send_price:'50.25'},11,foreign==='scope'?R.scope('store',4,7):R.scope(),foreign==='consistency'?'d'.repeat(64):R.consistency)};}});try{assert.equal(r.page.statistics.value,null);assert.equal(r.page.orders.value.length,0);assert.match(r.page.controller.error.value,/变化/);}finally{r.stop();}}});
test('hide clears all PII synchronously and aborts pending page reads',async()=>{const r=await start();try{assert.equal(r.page.orders.value.length,1);r.hooks.onHide();assert.equal(r.page.orders.value.length,0);assert.equal(r.page.statistics.value,null);assert.equal(r.page.controller.context.value,null);}finally{r.stop();}});
test('late account response cannot replay another actor or current identity',async()=>{const late=R.deferred();let first=true;const r=R.runtime({send(call,p){if(p.endsWith('/orders')&&first){first=false;return late.promise;}}});try{await r.start(query);r.auth.setLogin('actor22',22);await R.tick();late.resolve({data:R.envelope({list:[R.order()],count:1,page:1,limit:15,has_more:false,unsend:2,send:3},11)});await R.tick();assert.equal(r.page.orders.value.length,0);assert.equal(r.page.controller.selected.value,null);assert.ok(r.aborts.length>0);}finally{r.stop();}});
test('daily and order pagination have separate page cursors and real date values',async()=>{const r=await start({send(call,p){if(p.endsWith('/daily'))return{data:R.envelope({list:[{date:call.data.page===1?'2026-10-03':'2026-10-02',time:call.data.page===1?'2026-10-03':'2026-10-02',price:'50.25',count:3}],count:2,page:call.data.page,limit:call.data.limit,has_more:call.data.page===1})};if(p.endsWith('/orders'))return{data:R.envelope({list:[R.order(call.data.page===1?101:102)],count:2,page:call.data.page,limit:call.data.limit,has_more:call.data.page===1,unsend:2,send:3})};}});try{await r.page.loadMoreDaily();await r.page.loadMoreOrders();assert.equal(r.page.daily.value.length,2);assert.equal(r.page.orders.value.length,2);assert.deepEqual(r.calls.filter(c=>c.url.endsWith('/daily')).map(c=>c.data.page),[1,2]);assert.deepEqual(r.calls.filter(c=>c.url.endsWith('/orders')).map(c=>c.data.page),[1,2]);}finally{r.stop();}});
test('period and custom range are canonical and all statistic taps reach orders or daily',async()=>{const r=await start();try{r.page.changePeriod({detail:{value:1}});await R.tick();assert.ok(r.calls.at(-1).data.data==='yesterday');r.page.startDate.value='2026-10-01';r.page.endDate.value='2026-10-03';r.page.applyRange();await R.tick();assert.equal(r.calls.at(-1).data.data,'2026-10-01~2026-10-03');r.page.chooseStatus(2);await R.tick();assert.equal(r.calls.findLast(c=>c.url.endsWith('/orders')).data.type,2);r.page.chooseTab('daily');assert.equal(r.page.tab.value,'daily');}finally{r.stop();}});
test('full assigned detail consumes coupons gift metadata promotions custom form money and true maps',async()=>{const r=await start({component:'pages/delivery/orderDetail.vue'}, {...query,orderId:'101'});try{assert.equal(r.page.order.value.id,101);const html=await R.markup(r);for(const text of ['赠送优惠券','客户提交内容','真实促销标题','首单优惠','门店位置','核销记录'])assert.ok(html.includes(text),text);r.page.mapCustomer();assert.equal(r.toasts.length,0);r.page.mapStore();assert.equal(r.toasts[0].map.latitude,1.2);r.page.phone(r.page.order.value.user_phone);assert.equal(r.toasts[1].phone,'12345678901');}finally{r.stop();}});
test('disabled action and cancelled confirmation allocate no UUID and send no write',async()=>{for(const cancelled of [true,false]){const r=await start({modal:!cancelled});try{if(cancelled)assert.equal(await r.page.controller.execute(R.operation(),{available:true,reason:''}),null);else await assert.rejects(r.page.controller.execute(R.operation(),{available:false,reason:'配送账本尚未安装'}),/账本/);assert.equal(writes(r).length,0);assert.equal(r.page.controller.pending.value.length,0);}finally{r.stop();}}});
test('partial and complete receipts match frozen original wire hash and clear durable intent',async()=>{for(const outcome of ['partial-delivered','delivered']){const r=await start({outcome});try{const receipt=await r.page.controller.execute(R.operation(),{available:true,reason:''});assert.equal(receipt.outcome,outcome);assert.equal(r.page.controller.pending.value.length,0);assert.equal(writes(r).length,1);assert.equal(writes(r)[0].data.payload.code,'001234567890');assert.match(writes(r)[0].header['Idempotency-Key'],/^[a-f0-9-]{36}$/);}finally{r.stop();}}});
test('lost reply persists full original intent and null receipt never proves unexecuted',async()=>{const r=await start({send(call,p){if(p.endsWith('/writeoff'))return{transport:'lost reply'};}});try{await assert.rejects(r.page.controller.execute(R.operation(),{available:true,reason:''}));assert.equal(r.page.controller.pending.value.length,1);const intent=r.page.controller.pending.value[0];assert.deepEqual(intent.body,R.operation());await r.page.controller.checkIntent(intent);assert.equal(r.page.controller.pending.value.length,1);assert.equal(writes(r).length,1);assert.match(r.page.controller.operationError.value,/不要重复/);}finally{r.stop();}});
test('explicit same-key replay reuses byte-equivalent original payload without a second intent',async()=>{let first=true;const r=await start({send(call,p){if(p.endsWith('/writeoff')&&first){first=false;return{transport:'lost reply'};}}});try{await assert.rejects(r.page.controller.execute(R.operation(),{available:true,reason:''}));const intent=r.page.controller.pending.value[0];await r.page.controller.restoreIntent(intent);assert.equal(r.page.controller.pending.value.length,0);assert.equal(writes(r).length,2);assert.equal(writes(r)[0].header['Idempotency-Key'],writes(r)[1].header['Idempotency-Key']);assert.deepEqual(writes(r)[0].data,writes(r)[1].data);}finally{r.stop();}});
test('rollback rejection with zero execution identity is not success and needs acknowledgment',async()=>{const r=await start({outcome:'rollback-rejected'});try{const receipt=await r.page.controller.execute(R.operation(),{available:true,reason:''});assert.equal(receipt.delivery_id,0);assert.equal(r.page.controller.pending.value.length,1);assert.match(r.page.controller.operationError.value,/未执行/);r.page.controller.acknowledge(r.page.controller.pending.value[0]);assert.equal(r.page.controller.pending.value.length,0);}finally{r.stop();}});
test('receipt hash mismatch and foreign actor do not clear original intent',async()=>{for(const mismatch of ['hash','actor']){const r=await start({send(call,p){if(p.endsWith('/writeoff')){const row=R.receipt(call);if(mismatch==='hash')row.request_hash='d'.repeat(64);else row.actor_uid=22;return{data:{receipt:row,replayed:false}};}}});try{await assert.rejects(r.page.controller.execute(R.operation(),{available:true,reason:''}));assert.equal(r.page.controller.pending.value.length,1);assert.equal(writes(r).length,1);}finally{r.stop();}}});
test('role withdrawal preserves owner recovery but hides all former PII and cannot replay',async()=>{let withdrawn=false;const r=await start({send(call,p){if(p.endsWith('/writeoff'))return{transport:'lost reply'};if(p.endsWith('/context')&&withdrawn)return{status:403,msg:'配送权限已撤销'};}});try{await assert.rejects(r.page.controller.execute(R.operation(),{available:true,reason:''}));const intent=r.page.controller.pending.value[0];withdrawn=true;await r.page.controller.load();assert.equal(r.page.orders.value.length,0);assert.equal(r.page.controller.pending.value.length,1);await r.page.controller.restoreIntent(intent);assert.equal(writes(r).length,1);await r.page.controller.checkIntent(intent);assert.ok(r.calls.at(-1).url.endsWith(intent.request_key));}finally{r.stop();}});
test('account switch hides old intent and does not erase its original body',async()=>{const r=await start({send(call,p){if(p.endsWith('/writeoff'))return{transport:'lost reply'};}});try{await assert.rejects(r.page.controller.execute(R.operation(),{available:true,reason:''}));const intent=r.page.controller.pending.value[0];r.auth.setLogin('actor22',22);await R.tick();assert.equal(r.page.controller.pending.value.length,0);r.auth.setLogin('actor11',11);await R.tick();assert.equal(r.page.controller.pending.value.length,1);assert.deepEqual(r.page.controller.pending.value[0].body,intent.body);}finally{r.stop();}});
test('portable operation SHA matches Node independent canonical hash including leading-zero code',async()=>{const r=await start();try{const u=r.load(path.join(R.root,'src/utils/deliveryWorkbench.ts'));assert.equal(u.deliveryIntentHash(11,R.operation()),require('./merchant-orders-runtime.cjs').digest({version:'delivery-writeoff-operation-v1',actor_uid:11,kind:'delivery_writeoff',input:R.operation()}));for(const mutate of [o=>o.payload.code='123',o=>o.payload.items[0].quantity=0,o=>o.scope_kind='store'&& (o.store_id=0),o=>o.payload.items.push({...o.payload.items[0]})]){const o=R.operation();mutate(o);assert.equal(u.isDeliveryInput(o),false);}}finally{r.stop();}});
test('manual member barcode returns multiple scoped orders without submitting any fulfillment',async()=>{const r=await start({component:'pages/delivery/scanning.vue',send(call,p){if(p.endsWith('/writeoff/info'))return{data:R.envelope({list:[R.preview(101),R.preview(102)],lookup_kind:'member-barcode'})};}});try{r.page.code.value='MEMBER-ABC';await r.page.lookup();assert.equal(r.page.previews.value.length,2);assert.equal(writes(r).length,0);assert.equal(r.calls.at(-1).data.code,'MEMBER-ABC');const html=await R.markup(r);assert.ok(html.includes('ORDER_102'));r.page.controller.go('scanDetail',{orderId:102});assert.ok(r.navigations.at(-1).includes('orderId=102'));assert.ok(!r.navigations.at(-1).includes('MEMBER'));}finally{r.stop();}});
test('12-digit lookup preserves leading zeros and rejects multi-order response',async()=>{const r=await start({component:'pages/delivery/scanning.vue',send(call,p){if(p.endsWith('/writeoff/info'))return{data:R.envelope({list:[R.preview(101),R.preview(102)],lookup_kind:'order-code'})};}});try{r.page.code.value='001234567890';await r.page.lookup();assert.equal(r.calls.at(-1).data.code,'001234567890');assert.equal(r.page.previews.value.length,0);assert.match(r.page.pageError.value,/不匹配/);}finally{r.stop();}});
test('native scan only fills input and ignores late callbacks after scope loss',async()=>{const r=await start({component:'pages/delivery/scanning.vue'});try{r.page.nativeScanAvailable.value=true;r.page.scan();r.scanCallback.success({result:'001234567890'});assert.equal(r.page.code.value,'001234567890');assert.equal(r.calls.length,1);r.page.scan();r.hooks.onHide();r.scanCallback.success({result:'MEMBER-NEW'});assert.equal(r.page.code.value,'');assert.equal(writes(r).length,0);}finally{r.stop();}});
test('unsafe barcode and late code lookup cannot replay previous input',async()=>{const late=R.deferred();const r=await start({component:'pages/delivery/scanning.vue',send(call,p){if(p.endsWith('/writeoff/info'))return late.promise;}});try{r.page.code.value='bad\ncode';await r.page.lookup();assert.equal(r.calls.length,1);r.page.code.value='MEMBER-OLD';const task=r.page.lookup();await R.tick();r.page.code.value='MEMBER-NEW';late.resolve({data:R.envelope({list:[R.preview()],lookup_kind:'member-barcode'})});await task;assert.equal(r.page.previews.value.length,0);assert.equal(r.page.reading.value,false);}finally{r.stop();}});
test('scan detail consumes actual records and never labels unknown historical operator as current courier',async()=>{const r=await start({component:'pages/delivery/scanDetail.vue'},{...query,orderId:'101',tab:'records'});try{assert.equal(r.page.preview.value.id,101);assert.equal(r.page.records.value[0].writeoff_num,1);assert.equal(r.page.operatorLabel(R.record()),'历史操作人员');const html=await R.markup(r);assert.ok(html.includes('历史操作人员'));assert.ok(html.includes('核销 1 件 / 次'));assert.ok(html.includes('2026-10-03 10:00'));}finally{r.stop();}});
test('record pagination loads actual new row IDs and rejects duplicate page',async()=>{const r=await start({component:'pages/delivery/scanDetail.vue',send(call,p){if(p.endsWith('/records'))return{data:R.envelope({list:[R.record(call.data.page===1?30:31)],count:2,page:call.data.page,limit:15,has_more:call.data.page===1})};}},{...query,orderId:'101'});try{await r.page.loadMoreRecords();assert.deepEqual(r.page.records.value.map(row=>row.id),[30,31]);assert.equal(r.calls.at(-1).data.page,2);}finally{r.stop();}});
test('actual quantity panel bounds per-cart integers and submits partial selected quantities',async()=>{const r=await start(),mounted=R.mountedPanel(r,{controller:r.page.controller,preview:R.preview(),freshRequired:false});try{const p=mounted.panel,cart=R.preview().cart_info[0];p.setQuantity(cart,'4');assert.equal(p.quantities.value[1],0);assert.match(p.localError.value,/整数/);p.toggle(cart);p.adjust(cart,1);assert.equal(p.total.value,2);await p.submit();assert.deepEqual(writes(r)[0].data.payload.items,[{order_cart_id:1,quantity:2}]);assert.deepEqual(mounted.events,[['confirmed','partial-delivered']]);}finally{mounted.stop();r.stop();}});
test('actual type4 card consumes remaining times and window restrictions without switching actor',async()=>{const r=await start(),preview=R.preview();preview.product_type=4;preview.cart_info[0].product_type=4;preview.cart_info[0].write_times=10;preview.cart_info[0].write_surplus_times=2;const expired={...preview.cart_info[0],id:2,write_end:Math.floor(Date.now()/1000)-1};preview.cart_info.push(expired);const mounted=R.mountedPanel(r,{controller:r.page.controller,preview,freshRequired:false});try{mounted.panel.selectAll();assert.equal(mounted.panel.quantities.value[1],2);assert.equal(mounted.panel.quantities.value[2],undefined);await mounted.panel.submit();assert.deepEqual(writes(r)[0].data.payload.items,[{order_cart_id:1,quantity:2}]);assert.equal(writes(r)[0].data.delivery_id,7);assert.ok(!r.navigations.some(url=>url.includes('operator')));}finally{mounted.stop();r.stop();}});
test('partial receipt forces explicit fresh preview and cannot reuse rotated verification code',async()=>{let rotated=false;const r=await start({component:'pages/delivery/scanDetail.vue',send(call,p){if(p.endsWith('/writeoff/info')&&rotated){const preview=R.preview();preview.verify_code='009876543210';preview.revision='d'.repeat(64);preview.cart_info[0].write_surplus_times=2;return{data:R.envelope({list:[preview],lookup_kind:'order-id'})};}}},{...query,orderId:'101'});try{r.page.confirmed('partial-delivered');assert.equal(r.page.freshRequired.value,true);assert.equal(r.page.records.value.length,0);rotated=true;await r.page.controller.load();assert.equal(r.page.preview.value.verify_code,'009876543210');assert.equal(r.page.freshRequired.value,false);assert.equal(writes(r).length,0);}finally{r.stop();}});
test('unavailable ledger panel cannot select quantities or allocate new operation',async()=>{const r=await start(),preview=R.preview();preview.actions.writeoff={available:false,reason:'配送账本或执行权限尚未配置'};const mounted=R.mountedPanel(r,{controller:r.page.controller,preview,freshRequired:false});try{mounted.panel.selectAll();mounted.panel.toggle(preview.cart_info[0]);await mounted.panel.submit();assert.equal(writes(r).length,0);assert.equal(r.page.controller.pending.value.length,0);}finally{mounted.stop();r.stop();}});
test('account switch while explicit confirmation is pending cannot allocate or send',async()=>{const r=await start();let confirm;try{r.uni.showModal=call=>{confirm=()=>call.success({confirm:true});};const task=r.page.controller.execute(R.operation(),{available:true,reason:''});await R.tick();r.auth.setLogin('actor22',22);confirm();assert.equal(await task,null);assert.equal(writes(r).length,0);assert.equal(r.page.controller.pending.value.length,0);}finally{r.stop();}});
test('bounded authenticated request rejects a lost response and aborts its native task',async()=>{const late=R.deferred(),r=await start({send(call,p){if(p.endsWith('/statistics')&&call.data.deadline)return late.promise;}});try{const api=r.load(path.join(R.root,'src/api/deliveryWorkbench.ts')),requests=api.createDeliveryRequests(()=>true,20);await assert.rejects(requests.request('/delivery/workbench/statistics','GET',{deadline:true}),/超时/);assert.ok(r.aborts.length);requests.abort();late.resolve({data:{}});}finally{r.stop();}});
test('foreign assigned order UID or store is rejected before PII is rendered',async()=>{for(const foreign of ['uid','store']){const r=await start({send(call,p){if(p.endsWith('/orders')){const order=R.order();if(foreign==='uid')order.delivery_uid=22;else order.store_id=4;return{data:R.envelope({list:[order],count:1,page:1,limit:15,has_more:false,unsend:2,send:3})};}}});try{assert.equal(r.page.orders.value.length,0);assert.match(r.page.controller.error.value,/配送范围/);}finally{r.stop();}}});
test('permission error on later pagination clears existing PII and authority synchronously',async()=>{let failed=false;const r=await start({send(call,p){if(p.endsWith('/orders')){if(failed)return{status:403,msg:'配送身份已撤销'};return{data:R.envelope({list:[R.order()],count:2,page:1,limit:15,has_more:true,unsend:2,send:3})};}}});try{assert.equal(r.page.orders.value.length,1);failed=true;await r.page.loadMoreOrders();assert.equal(r.page.orders.value.length,0);assert.equal(r.page.controller.context.value,null);assert.match(r.page.controller.error.value,/撤销/);}finally{r.stop();}});
test('explicit abandon preserves original UUID and rejection is acknowledged separately',async()=>{const r=await start({send(call,p){if(p.endsWith('/writeoff'))return{transport:'lost reply'};}});try{await assert.rejects(r.page.controller.execute(R.operation(),{available:true,reason:''}));const intent=r.page.controller.pending.value[0];await r.page.controller.restoreIntent(intent,true);const abandoned=r.calls.at(-1);assert.ok(abandoned.url.endsWith('/operation/abandon'));assert.equal(abandoned.header['Idempotency-Key'],intent.request_key);assert.deepEqual(abandoned.data,intent.body);assert.equal(r.page.controller.pending.value.length,1);assert.match(r.page.controller.operationError.value,/放弃/);r.page.controller.acknowledge(intent);assert.equal(r.page.controller.pending.value.length,0);}finally{r.stop();}});
test('failed durable storage write prevents submission instead of losing recovery body',async()=>{const r=await start();try{r.uni.setStorageSync=()=>{throw Error('quota exceeded');};await assert.rejects(r.page.controller.execute(R.operation(),{available:true,reason:''}),/quota/);assert.equal(writes(r).length,0);}finally{r.stop();}});
test('window deadline clears selected quantity and triggers a real read without allocating a write',async()=>{const r=await start({component:'pages/delivery/scanDetail.vue'},{...query,orderId:'101'}),preview=R.preview();preview.cart_info[0].write_end=Math.floor(Date.now()/1000)+60;const mounted=R.mountedPanel(r,{controller:r.page.controller,preview,freshRequired:false});try{mounted.panel.toggle(preview.cart_info[0]);assert.equal(mounted.panel.total.value,1);mounted.panel.clock.value=preview.cart_info[0].write_end+1;assert.equal(mounted.panel.total.value,0);assert.ok(mounted.events.some(event=>event[0]==='expired'));const before=r.calls.filter(call=>call.url.endsWith('/writeoff/info')).length;r.page.windowChanged();await R.tick();assert.equal(r.calls.filter(call=>call.url.endsWith('/writeoff/info')).length,before+1);assert.equal(writes(r).length,0);}finally{mounted.stop();r.stop();}});
test('legacy requested delivery skips platform-only operator profile and enters scoped scanner',async()=>{const r=await start({component:'pages/operator/writeoff.vue'},{role:'delivery',code:'001234567890'});try{assert.equal(r.calls.length,0);assert.deepEqual(r.navigations,['/pages/delivery/scanning']);assert.equal(r.page.previewOrder.value,null);await r.page.preview();await r.page.execute();r.page.scan();assert.equal(r.calls.length,0);assert.ok(r.navigations.every(url=>url==='/pages/delivery/scanning'));}finally{r.stop();}});
