    // 秒杀时间段 + 秒杀商品 (幂等, M17 补)
    await container.db.execute(
      sql`DELETE FROM store_seckill_time WHERE id IN (1,2,3)`,
    );
    await container.db.execute(sql`
      INSERT INTO "store_seckill_time" ("id", "start_time", "end_time", "status", "add_time")
