          if (menu.id === 720 && menu.authType === 1 && menu.menuPath === '/admin/setting/delivery_service/index'
            && menu.uniqueAuth === 'setting-delivery-service' && menu.apiUrl === '' && menu.methods === '') {
            resolved.add('order.view');
          }
          continue;
