 for(const row of proof.sources){
  it(`pins whole actual producer and exact predecessor ${row.file}`,()=>{const actual=read(row.file);expect(sha(actual)).toBe(row.after_sha256);expect(sha(reverseExpressSource(row.file,actual))).toBe(row.before_sha256);expect(sha(readExpressPredecessor(resolve(root,row.file)))).toBe(row.before_sha256);});
  it(`rejects source truncation, append, duplication and forged mappings ${row.file}`,()=>{const actual=read(row.file);for(const bad of [actual.slice(1),actual+'\n// unreviewed\n',actual+actual])expect(()=>reverseExpressSource(row.file,bad)).toThrow();for(const key of ['before_sha256','after_sha256'] as const){const forged=structuredClone(proof);forged.sources.find(r=>r.file===row.file)![key]='0'.repeat(64);expect(()=>reverseExpressSource(row.file,actual,forged)).toThrow();}const forged=structuredClone(proof);forged.sources.find(r=>r.file===row.file)!.edits[0]!.after_line=2;expect(()=>reverseExpressSource(row.file,actual,forged)).toThrow();});
