 }
 for(const row of proof.full_additions)it(`pins complete new source ${row.file}`,()=>{const raw=readFileSync(resolve(root,row.file));expect(raw.byteLength).toBe(row.bytes);expect(sha(raw)).toBe(row.sha256);});
 for(const row of proof.PHP_sources)it(`pins full fixed PHP source ${row.file}`,()=>{expect(proof.PHP_ref).toBe('8ed2a5b139f9170dd11b0dff91803f2fd59e40a5');expect(sha(row.raw_utf8)).toBe(row.sha256);expect(new TextEncoder().encode(row.raw_utf8).byteLength).toBe(row.bytes);});
 const frozen=Object.entries(proof.frozen_predecessor_evidence);for(let start=0;start<frozen.length;start+=64)it(`keeps accepted dated evidence bytes ${start+1}..${Math.min(start+64,frozen.length)}`,()=>{for(const[file,hash]of frozen.slice(start,start+64))expect(sha(readFileSync(resolve(root,file))),file).toBe(hash);});
 it('preserves existing issue/consumer SQL, auth/storage and runtime profile plan',()=>{for(const[file,hash]of Object.entries(proof.observed_unchanged))expect(sha(readFileSync(resolve(root,file))),file).toBe(hash);});
 it('rebuilds actual API inventory with five new calls and no unresolved or unavailable variants',()=>{const report=buildAdminFrontendApiAuditReport(),raw=read(proof.current_report.file);expect(JSON.stringify(report,null,2)+'\n').toBe(raw);expect(sha(raw)).toBe(proof.current_report.sha256);expect(report.counts).toEqual({callSites:728,pathVariants:766,registered:766,executable:766,controlledUnavailable:0,unregistered:0,unresolved:0});const before=buildExpressPredecessorApiAuditReport();for(const c of before.calls)expect(report.calls).toContainEqual(c);expect(report.calls.filter(c=>c.source==='view/admin-ts/src/api/expressAuthor.ts')).toHaveLength(5);});
 it('composes current express and frozen platform sources without changing old helper bytes',()=>{for(const f of ['view/admin-ts/src/router/index.ts','workers-ts/src/routes/adminapi.ts','workers-ts/src/migrations/auditRuntimeBusinessPrivileges.ts','.github/workflows/workers-runtime-linux.yml']){const prior=reverseExpressSource(f,read(f));expect(readExpressPredecessor(resolve(root,f),'utf8')).toBe(prior);expect(readPlatformMenuPredecessor(resolve(root,f),'utf8')).toBe(reversePlatformMenuSource(f,prior));}expect(sha(proof.previous_report.raw_utf8)).toBe(platformMenuSourceBinding.current_report.sha256);});
 it('binds all six original active field mappings and explicit PHP defect/completeness differences',()=>{expect(EXPRESS_FIELDS.map(f=>[f.flag,f.field])).toEqual([['partnerId','account'],['partnerKey','key'],['net','netName'],['checkMan','courierName'],['partnerName','customerName'],['isCode','codeName']]);expect(proof.boundaries.legacy).toContain('last three');expect(proof.boundaries.provider).toContain('response snapshot');expect(read('view/admin-ts/src/router/index.ts')).toContain('alias: "/admin/setting/freight/express/index"');expect(read('.github/workflows/workers-runtime-linux.yml')).toContain('npm run test:express-author');});
});

