function source(file:string){const row=proof.sources.find(r=>r.file===file);if(!row)throw Error(`Missing complete source binding: ${file}`);return row;}

describe('ordinary member-level author, exact additive sources and preserved accepted predecessors',()=>{
 for(const row of proof.sources){
  it(`pins whole current source and complete predecessor ${row.file}`,()=>{const actual=read(row.file);expect(sha(actual)).toBe(row.after_sha256);expect(sha(reverseLevelSource(row.file,actual))).toBe(row.before_sha256);expect(sha(readLevelPredecessor(resolve(root,row.file)))).toBe(row.before_sha256);});
  it(`rejects source truncation, append, duplication and forged inverses ${row.file}`,()=>{const actual=read(row.file);for(const bad of [actual.slice(1),actual+'\n// unreviewed\n',actual+actual])expect(()=>reverseLevelSource(row.file,bad)).toThrow();for(const key of ['before_sha256','after_sha256'] as const){const forged=structuredClone(proof);forged.sources.find(r=>r.file===row.file)![key]='0'.repeat(64);expect(()=>reverseLevelSource(row.file,actual,forged)).toThrow();}for(const key of ['before_line','after_line'] as const){const forged=structuredClone(proof);forged.sources.find(r=>r.file===row.file)!.edits[0]![key]=2;expect(()=>reverseLevelSource(row.file,actual,forged)).toThrow();}const forged=structuredClone(proof);forged.sources.find(r=>r.file===row.file)!.edits.push({...row.edits[0]!});expect(()=>reverseLevelSource(row.file,actual,forged)).toThrow();});
  if(row.file.startsWith('workers-ts/test/')&&row.file!=='workers-ts/test/user-level-cache-authority.test.ts')it(`preserves all predecessor assertions and counterexamples ${row.file}`,()=>{expect(stripImports(row.edits[0]!.after_source)).toBe(stripImports(row.edits[0]!.before_source));});
 }
 for(const row of proof.full_additions)it(`pins complete new source ${row.file}`,()=>{const raw=readFileSync(resolve(root,row.file));expect(raw.byteLength).toBe(row.bytes);expect(sha(raw)).toBe(row.sha256);});
 for(const row of proof.PHP_sources)it(`pins complete fixed PHP source ${row.file}`,()=>{expect(proof.PHP_ref).toBe('8ed2a5b139f9170dd11b0dff91803f2fd59e40a5');expect(sha(row.raw_utf8)).toBe(row.sha256);expect(new TextEncoder().encode(row.raw_utf8).byteLength).toBe(row.bytes);});
 const frozen=Object.entries(proof.frozen_predecessor_evidence);
 for(let start=0;start<frozen.length;start+=64)it(`retains accepted dated proof, docs and helpers ${start+1}..${Math.min(start+64,frozen.length)}`,()=>{for(const[file,hash]of frozen.slice(start,start+64))expect(sha(readFileSync(resolve(root,file))),file).toBe(hash);});

 it('retains all observed existing consumers, authority and shared privilege plans',()=>{for(const[file,hash]of Object.entries(proof.observed_unchanged))expect(sha(readFileSync(resolve(root,file))),file).toBe(hash);for(const required of ['workers-ts/src/services/user/MobileUserManagementCore.ts','workers-ts/src/services/order/OrderRewardService.ts','workers-ts/src/services/product/StoreProductService.ts','workers-ts/src/services/order/StoreCartService.ts','workers-ts/src/services/order/StoreOrderCreateService.ts','workers-ts/src/migrations/runtimeBusinessPrivilegePlan.ts','view/admin-ts/src/utils/auth.ts','view/admin-ts/src/utils/request.ts','view/admin-ts/src/stores/auth.ts'])expect(Object.hasOwn(proof.observed_unchanged,required),required).toBe(true);});
 it('rebuilds the real current API inventory with exactly six new executable calls',()=>{const actual=buildAdminFrontendApiAuditReport(),raw=read(proof.current_report.file);expect(JSON.stringify(actual,null,2)+'\n').toBe(raw);expect(sha(raw)).toBe(proof.current_report.sha256);expect(actual.counts).toEqual({callSites:734,pathVariants:772,registered:772,executable:772,controlledUnavailable:0,unregistered:0,unresolved:0});const before=buildLevelPredecessorApiAuditReport();expect(before.counts.callSites).toBe(728);expect(before.counts.pathVariants).toBe(766);for(const call of before.calls)expect(actual.calls).toContainEqual(call);const added=actual.calls.filter(call=>call.source==='view/admin-ts/src/api/levelAuthor.ts');expect(added).toHaveLength(6);expect(added.map(call=>[call.method,call.path])).toEqual([['GET','/level/catalog'],['POST','/level/author/commit'],['GET','/level/author/receipt/:param'],['POST','/level/author/resolve'],['GET','/level/attachment-options'],['GET','/level/attachment-categories']]);});
 it('composes the new exact inverse before the frozen Express layer',()=>{for(const file of ['workers-ts/src/routes/adminapi.ts','view/admin-ts/src/router/index.ts','workers-ts/src/migrations/auditRuntimeBusinessPrivileges.ts','.github/workflows/workers-runtime-linux.yml']){const prior=reverseLevelSource(file,read(file));expect(readLevelPredecessor(resolve(root,file),'utf8')).toBe(prior);expect(readExpressPredecessor(resolve(root,file),'utf8')).toBe(reverseExpressSource(file,prior));}expect(sha(proof.previous_report.raw_utf8)).toBe(expressSourceBinding.current_report.sha256);expect(proof.full_additions.some(row=>row.file==='workers-ts/test/helpers/levelSourceBinding.ts')).toBe(false);});
 it('leaves unrelated source text unchanged instead of applying a generalized reverse patch',()=>{const text='unrelated source with /level/catalog and ordinary member level';expect(reverseLevelSource('not/a/producer.ts',text)).toBe(text);});
 it('binds the nine active original form controls and excludes commented expiry metadata',()=>{const php=proof.PHP_sources.find(row=>row.file==='app/services/user/level/UserLevelServices.php');expect(php).toBeDefined();const form=between(php!.raw_utf8,'    public function edit(int $id)','        return create_form(').replace(/^\s*\/\/.*$/gmu,'');const controls=Array.from(form.matchAll(/Form::(?:input|number|frameImage|color|radio|textarea)\('([^']+)'/gu),match=>match[1]);expect(controls).toEqual([...LEVEL_FIELDS]);expect(controls).not.toContain('valid_date');expect(form).toContain("'图标(656*300)'");expect(form).toContain("'会员背景(750*990)'");expect(newLevelValues()).toEqual({name:'',grade:0,discount:'100',exp_num:0,icon:'',image:'',color:'',is_show:0,explain:''});});
 it('preserves getLevel, explicit cache cleanup, user info and the entire activation tail byte for byte',()=>{const row=source('workers-ts/src/services/user/UserLevelService.ts'),before=row.edits[0]!.before_source,after=row.edits[0]!.after_source;expect(between(after,'  async getLevel(','  /** 等级列表')).toBe(between(before,'  async getLevel(','  /** 等级列表'));expect(between(after,'  /** 用户等级信息','  private async activationConfig(')).toBe(between(before,'  /** 用户等级信息','  private async activationConfig('));expect(after.slice(after.indexOf('  private async activationConfig('))).toBe(before.slice(before.indexOf('  private async activationConfig(')));expect(after).toContain('discount: Number(row.discount) || 100');expect(after).toContain('discount: Number(r.discount) || 100');expect(proof.boundaries.pricing).toContain('never interpret zero as free');});
 it('records the cache-fixture exception separately while retaining all old pricing and cache assertions',()=>{const row=source('workers-ts/test/user-level-cache-authority.test.ts'),before=row.edits[0]!.before_source,after=row.edits[0]!.after_source;expect(before).not.toBe(after);expect(proof.boundaries.cache_fixture).toContain('not an import-only change');expect(proof.boundaries.cache_fixture).toContain('clear user.level');expect(after).toContain('createAdminLevelFixture');expect(after).toContain("c.set('adminId',1)");expect(after).toContain('await f.db.update(user).set({level:0})');expect(between(after,'  async function expectCurrentQuote(','  it.each(')).toBe(between(before,'  async function expectCurrentQuote(','  it.each('));const oldAssertions=before.split('\n').filter(line=>/^\s*(?:expect\(|await expectCurrentQuote\()/u.test(line));for(const line of oldAssertions)expect(after).toContain(line);});
 it('binds independently checked creation defaults and full-row/history rollback readback',()=>{const service=read('workers-ts/src/services/admin/AdminLevelAuthorService.ts');expect(service).toContain("merId:0,money:'0.00',validDate:0,isForever:1,isPay:0,isDel:0");expect(service).toContain('Object.entries(inserted).some(');expect(service).toContain('expected.set(id,saved)');expect(service).toContain('history.map(r=>({...r,isDel:1}))');expect(service).toContain('等级完整写后回读不一致');expect(proof.boundaries.legacy).toContain('create validDate0/isForever1/isPay0/money0.00');expect(proof.boundaries.constraints).toContain('Every inserted field independently verified');});
 it('preserves the original discount spelling for numeric equality and changes only explicit active values',()=>{const service=read('workers-ts/src/services/admin/AdminLevelAuthorService.ts');expect(service).toContain('Number(v.discount)===Number(old.discount)');expect(service).toContain("discount:discountSame?old!.discount:Number(v.discount).toFixed(2)");expect(service).toContain('历史0只能原样保留');expect(service).toContain('非平台历史等级只能查看');expect(proof.boundaries.constraints).toContain('Global all nondeleted rows');expect(proof.boundaries.legacy).toContain('arbitrary set_value are not restored');});
 it('binds exact two-slot stable-reference publication without authorizing unknown or business fields',()=>{const policy=read('workers-ts/src/services/user/LevelAssetPolicy.ts');expect(policy).toContain("const fields = ['icon', 'image'] as const");expect(policy).toContain("row.path === `/api/assets/${row.id}`");expect(policy).toContain("currentQuery.for('share', { noWait: true })");expect(policy).toContain('if (!changes.length) return');expect(policy).toContain('signAttachmentReferences(appKey, canonical)');expect(policy).not.toContain('decodeURIComponent');expect(policy).not.toContain('decodeHtml');expect(proof.boundaries.media).toContain('Exactly icon and image active slots');expect(proof.boundaries.media).toContain('no general attachment ACL expansion or uploading');});
 it('binds prior UUID before revision validation, owner recovery and real consumer read/write exclusion',()=>{const service=read('workers-ts/src/services/admin/AdminLevelAuthorService.ts'),mutate=service.slice(service.indexOf(' mutate(value:unknown'));expect(mutate.indexOf('await this.prior(tx,a)')).toBeLessThan(mutate.indexOf('a.revision!==before.revision'));expect(service).toContain('LOCK TABLE ONLY public.system_user_level IN ACCESS EXCLUSIVE MODE NOWAIT');expect(service).toContain('LOCK TABLE ONLY public.user, ONLY public.user_level IN SHARE ROW EXCLUSIVE MODE NOWAIT');expect(service).toContain('pg_advisory_xact_lock(731629,1)');expect(service).toContain("this.transaction(actor,true,true");expect(service).toContain("this.receiptInsert(tx,a,'not_applied'");const native=read('workers-ts/test/admin-level-native.test.ts');expect(native).toContain('await applyMobileUserState(port,');expect(native).toContain('await detectUserLevel(port,');expect(native).toContain("index===0?'RowShareLock':'AccessShareLock'");expect(native).toContain('Existing consumer finished without the real level-read barrier');expect(proof.boundaries.database).toContain('Real PG16 LOGIN test separate from PGlite session ports');});
 it('rejects contradictory committed and not-applied receipts before journal removal',()=>{const action:LevelAction={operation_id:'40000000-0000-4000-8000-000000000001',actor_id:1,operation:'update',target_id:7,revision:'a'.repeat(64),payload:{},payload_hash:'b'.repeat(64)};const {payload:_,...metadata}=action,committed={...metadata,state:'committed',result:{id:7,created:0,updated:1,count:1,revision:'c'.repeat(64)}};expect(levelReceipt(committed,action).state).toBe('committed');for(const result of [{...committed.result,id:8},{...committed.result,created:1},{...committed.result,updated:0}])expect(()=>levelReceipt({...committed,result},action)).toThrow();const notApplied={...metadata,state:'not_applied',result:{id:7,created:0,updated:0,count:0,revision:action.revision}};expect(levelReceipt(notApplied,action).state).toBe('not_applied');for(const result of [{...notApplied.result,count:1},{...notApplied.result,updated:1},{...notApplied.result,revision:'c'.repeat(64)}])expect(()=>levelReceipt({...notApplied,result},action)).toThrow();const create={...action,operation:'create' as const,target_id:0};const {payload:__,...createMetadata}=create;expect(()=>levelReceipt({...createMetadata,state:'committed',result:{...committed.result,id:0,created:1,updated:0}},create)).toThrow();expect(levelReceipt({...createMetadata,state:'committed',result:{...committed.result,id:9,created:1,updated:0}},create).result.id).toBe(9);});
 it('binds bounded legacy-sized bodies, captured picker query and journal-before-dispatch recovery',()=>{const controller=read('workers-ts/src/controllers/api/v1/AdminLevelAuthorController.ts'),state=read('view/admin-ts/src/utils/levelState.ts');expect(controller.match(/readBoundedJsonObject\(c\.req\.raw,512\*1024\)/gu)).toHaveLength(3);expect(state).toContain('q={page:p.page,limit:20,pid:p.pid,name:p.name}');expect(state).toContain('if(!valid())return;const raw=levelObject(await deps.options(q,c.signal))');expect(state).toContain('pickerRequest?.abort()');expect(state).toContain('deps.persist(s.actor,a);state.pending=copy(a)');expect(state).toContain('state.notice=\'\'');expect(proof.boundaries.recovery).toContain('512KiB bodies and journal');expect(proof.boundaries.recovery).toContain('absent receipt is unknown');});
 it('binds only the ordinary level route and dedicated test pipeline, leaving unrelated author domains intact',()=>{expect(read('view/admin-ts/src/router/index.ts')).toContain('alias: "/admin/vipuser/level/list"');expect(read('.github/workflows/workers-runtime-linux.yml')).toContain('npm run test:level-author');expect(JSON.parse(read('workers-ts/package.json')).scripts['test:level-author']).toContain('test/admin-level-source-binding.test.ts');expect(JSON.parse(read('view/admin-ts/package.json')).scripts['test:level-author']).toContain('scripts/level-page-runtime.test.cjs');expect(proof.boundaries.navigation).toContain('exactly two author image slots');});
});

