  for(const field of ['before_sha256','after_sha256','after_line']as const)it(`rejects forged ${field} ${entry.file}`,()=>{const changed=structuredClone(proof),row=changed.sources.find(r=>r.file===entry.file)!;if(field==='after_line')row.edits[0]!.after_line=2;else row[field]='0'.repeat(64);expect(()=>reverseBrowserLogSource(entry.file,read(entry.file),changed)).toThrow();});
 }
