 it('installs before mount and keeps meaningful runtime suites in the actual Admin CI chain',()=>{const main=read('view/admin-ts/src/main.ts'),script=JSON.parse(read('view/admin-ts/package.json')).scripts['test:browser-log'];expect(main.indexOf('installBrowserLog(app, router, useAuthStore(), request);')).toBeLessThan(main.indexOf('app.mount('));for(const file of ['browser-log-model-runtime.test.cjs','browser-log-page-runtime.test.cjs'])expect(script).toContain(file);expect(read('.github/workflows/workers-runtime-linux.yml')).toContain('npm run test:browser-log');expect(read('workers-ts/vitest.config.ts')).toContain('test/*.test.ts');});
});

