import { readAdminProfileThenErrorPagesPredecessor as readErrorPagesPredecessor, readAdminProfileThenErrorPagesThenBrowserLogPredecessor as readErrorPagesThenBrowserLogPredecessor, readAdminProfileThenErrorPagesThenBrowserLogThenConfigClassPredecessor as readErrorPagesThenBrowserLogThenConfigClassPredecessor } from './helpers/staffSourceBinding';
